solution.solution.cpp:
#include <cstdint>
#include <map>
#include <utility>
#include <vector>

class LinkSimulator
{
public:
    LinkSimulator(double latency, std::vector<bool> dropPattern, std::vector<double> extraDelay)
        : latency_{ latency }, dropPattern_{ std::move(dropPattern) }, extraDelay_{ std::move(extraDelay) }
    {
    }

    void send(double now, const std::vector<std::uint8_t>& packet)
    {
        const std::size_t k{ sent_++ };
        if (!dropPattern_.empty() && dropPattern_[k % dropPattern_.size()])
        {
            ++dropped_;
            return;
        }
        const double extra{ extraDelay_.empty() ? 0.0 : extraDelay_[k % extraDelay_.size()] };
        waiting_.emplace(std::pair{ now + latency_ + extra, k }, packet);
    }

    std::vector<std::vector<std::uint8_t>> receive(double now)
    {
        std::vector<std::vector<std::uint8_t>> out;
        while (!waiting_.empty() && waiting_.begin()->first.first <= now)
        {
            out.push_back(std::move(waiting_.begin()->second));
            waiting_.erase(waiting_.begin());
        }
        return out;
    }

    std::size_t inFlight() const { return waiting_.size(); }
    int dropped() const { return dropped_; }

private:
    double latency_;
    std::vector<bool> dropPattern_;
    std::vector<double> extraDelay_;
    std::size_t sent_{ 0 };
    int dropped_{ 0 };
    std::map<std::pair<double, std::size_t>, std::vector<std::uint8_t>> waiting_;
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("latency") {
    LinkSimulator link{ 50, {}, {} };
    link.send(0, { 1 });
    CHECK_EQ(link.inFlight(), 1u);
    CHECK(link.receive(49.9).empty());
    const auto got{ link.receive(50) };
    CHECK(got == (std::vector<Bytes>{ { 1 } }));
    CHECK_EQ(link.inFlight(), 0u);
    CHECK(link.receive(1000).empty());
}
TEST("dropping by pattern") {
    LinkSimulator link{ 10, { false, false, true }, {} };
    for (std::uint8_t i{ 0 }; i < 6; ++i) link.send(i, { i });
    CHECK_EQ(link.dropped(), 2);
    CHECK_EQ(link.inFlight(), 4u);
    CHECK(link.receive(100) == (std::vector<Bytes>{ { 0 }, { 1 }, { 3 }, { 4 } }));
}
TEST("reordering with extra delay") {
    LinkSimulator link{ 50, {}, { 0, 40, 20 } };
    link.send(0, { 'A' });
    link.send(10, { 'B' });
    link.send(20, { 'C' });
    CHECK(link.receive(70) == (std::vector<Bytes>{ { 'A' } }));
    CHECK(link.receive(100) == (std::vector<Bytes>{ { 'C' }, { 'B' } }));
}
TEST("ties keep the sending order") {
    LinkSimulator link{ 5, {}, {} };
    link.send(1, { 1 });
    link.send(1, { 2 });
    link.send(1, { 3 });
    CHECK(link.receive(6) == (std::vector<Bytes>{ { 1 }, { 2 }, { 3 } }));
}

